public void loadXml(string fileName, bool ignoreUnknown = false)
{
	ActivatorWrap.IgnoreUnknown = ignoreUnknown;
	defaultFileName = fileName;
	lock (syncObj)
	{
		string text = fileName.Replace(".xml", ".zip");
		bool flag = false;
		if (!File.Exists(fileName))
		{
			flag = true;
		}
		if (!File.Exists(fileName) && !File.Exists(text))
		{
			throw new FileNotFoundException("文件" + fileName + "不存在。");
		}
		try
		{
			FileInfo fileInfo = new FileInfo(fileName);
			fileInfo.Attributes = FileAttributes.Normal;
			XmlDocument xmlDocument = new XmlDocument();
			if (!flag)
			{
				xmlDocument = CreateXmlDoc(fileName);
				if (xmlDocument.LastChild.Name == xmlEncrypt.NodeNameplate)
				{
					string xml = xmlEncrypt.Decrypt(xmlDocument.LastChild.InnerText.Trim());
					xmlDocument = new XmlDocument();
					xmlDocument.LoadXml(xml);
				}
			}
			else
			{
				xmlDocument.Load(CompressUtil.DecompressToStream(text));
			}
			Init(xmlDocument.LastChild);
		}
		catch (Exception ex)
		{
			throw ex;
		}
		defaultFileName = fileName;
	}
	ActivatorWrap.IgnoreUnknown = false;
}

